using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Cosmos DB no longer supports indexes — remove HasIndex.
        // modelBuilder.Entity<Blog>().HasIndex(b => b.Name); // REMOVED

        // Breaking change 2: Discriminator property renamed from "Discriminator" to "$type".
        // Preserve old property name for existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 3: Id format changed from "EntityType|Key" to just "Key".
        // Preserve old id format for existing documents.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyIdValueGenerator>();
    }
}

// Breaking change 4: Sync I/O now throws by default in EF Core 9.
// All .ToList() / .SaveChanges() must become async, or opt-in to sync.
class Blog { public string Id { get; set; } public string Name { get; set; } }

