    // EF Core 9 uses "$type" instead of "Discriminator".
    // Since we kept "Discriminator" via HasDiscriminator(), raw SQL
    // queries like the one below still work. But if you hadn't
    // configured HasDiscriminator("Discriminator"), you would need:
    //   SELECT * FROM c WHERE c["$type"] = 'Blog'
    // instead of:
    //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
}

